using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Collections;
using System.Collections.Generic;
using System.Reflection;
using System.Web.Script.Serialization;
namespace PZ3D {
 static class ModSortingTests {
  static int assertions;
  sealed class Fixture {
   public readonly Engine E;public readonly string Root;
   public Fixture(){Root=Path.Combine(LauncherTestPaths.Root,"mod-order-review-"+Guid.NewGuid().ToString("N"));E=new Engine(Path.Combine(Root,"steamapps/common/ProjectZomboid"),Path.Combine(Root,"User"),Path.Combine(Root,"Data"),true);Put(E.Config,"{\"vmArgs\":[]}");Put(Path.Combine(E.Game,"game-version.txt"),"42.12.3");}
   public void Mod(string id,string extra=""){Put(Path.Combine(E.User,"mods",id,"42/mod.info"),"id="+id+"\n"+extra);}
  }
  static void Put(string path,string text){Directory.CreateDirectory(Path.GetDirectoryName(path));File.WriteAllText(path,text,new UTF8Encoding(false));}
  static void Check(bool value,string label){assertions++;if(!value)throw new Exception("FAIL: "+label);}
  static void Refuses(Action work,string label){bool refused=false;try{work();}catch{refused=true;}Check(refused,label);}
  static Dictionary<string,object> D(object value){var j=new JavaScriptSerializer();return j.Deserialize<Dictionary<string,object>>(j.Serialize(value));}
  static string[] Strings(Dictionary<string,object> row,string key){return ((IEnumerable)row[key]).Cast<object>().Select(x=>x.ToString()).ToArray();}
  static Dictionary<string,object> Sort(Fixture f,params string[] ids){return D(ModConfigurations.Sort(f.E,ids));}
  static void Original(Dictionary<string,object> row,string[] ids,string label){Check(Strings(row,"errors").Length>0&&!Convert.ToBoolean(row["changed"])&&Strings(row,"mods").SequenceEqual(ids),label);}
  static void Metadata(){var f=new Fixture();f.Mod("A");f.Mod("B");f.Mod("C");f.Mod("Declared","conflicts=B; C\nincompatible=\\A, B\n");var warnings=new List<string>();var entry=SaveProfiles.Entries(f.E,warnings).Single(x=>x.id=="Declared");Check(entry.conflicts.SequenceEqual(new[]{"B","C","A"}),"both explicit metadata keys merge and deduplicate canonical references");Check(entry.metadata["incompatible"]=="\\A, B","incompatible raw author evidence is retained");var before=new[]{"Declared","A"};Original(Sort(f,before),before,"incompatible prevents sorting without changing selected IDs/order");Check(Strings(Sort(f,"Declared"),"errors").Length==0,"unselected incompatible mod imposes no conflict");}
  static void Components(){var f=new Fixture();f.Mod("A","require=B\n");f.Mod("B","require=A\n");f.Mod("Tail","require=B\n");f.Mod("Tail2","require=Tail\n");f.Mod("D","loadBefore=E\n");f.Mod("E","loadBefore=D\n");f.Mod("Self","loadAfter=Self\n");f.Mod("Free");string[] ids={"Tail2","B","Tail","A","E","D","Free","Self"};var row=Sort(f,ids);Original(row,ids,"multiple dependency cycles preserve full original list");Check(row.ContainsKey("cycles")&&row.ContainsKey("blockedByCycles"),"cycle diagnostics expose distinct SCC and downstream fields");var cycles=((IEnumerable)row["cycles"]).Cast<IEnumerable>().Select(group=>group.Cast<object>().Select(x=>x.ToString()).ToArray()).ToArray();Check(cycles.Length==3&&cycles[0].SequenceEqual(new[]{"B","A"})&&cycles[1].SequenceEqual(new[]{"E","D"})&&cycles[2].SequenceEqual(new[]{"Self"}),"only exact cycle members are grouped in input order including self-loop");Check(Strings(row,"blockedByCycles").SequenceEqual(new[]{"Tail2","Tail"}),"downstream blocked IDs are separate from cycle members");Check(Strings(row,"errors").Where(x=>x.StartsWith("依赖或加载顺序存在循环")).All(x=>!x.Contains("Tail")),"cycle error never misidentifies blocked descendants");}
  static void Preservation(){var f=new Fixture();f.Mod("A");f.Mod("B","require=A\n");f.Mod("Free");string[] good={"B","Free","A"};Check(Strings(Sort(f,good),"mods").SequenceEqual(new[]{"Free","A","B"}),"stable Kahn retains existing choice of earliest available item");Check(!Convert.ToBoolean(Sort(f,"Free","A","B")["changed"]),"already valid relative order remains stable");var missing=new[]{" B ","Missing"," A "};Original(Sort(f,missing),missing,"missing source retains even original whitespace and order");Put(Path.Combine(f.E.Workshop,"123/mods/Duplicate/42/mod.info"),"id=A\n");var ambiguous=new[]{"B","A","Free"};Original(Sort(f,ambiguous),ambiguous,"ambiguous source leaves original list");var isolated=new Fixture();isolated.Mod("UnknownAuthor");isolated.Mod("Ordinary");var unrelated=Sort(isolated,"UnknownAuthor","Ordinary");Check(Strings(unrelated,"errors").Length==0&&!Convert.ToBoolean(unrelated["changed"]),"unknown compatibility is never invented as a conflict");Put(isolated.E.Mods,"VERSION = 1,\nmods\n{\n mod = UnknownAuthor,\n mod = Ordinary,\n}\nmaps\n{\n}\n");isolated.Mod("UnknownAuthor","incompatible=Ordinary\n");byte[] original=File.ReadAllBytes(isolated.E.Mods);Refuses(()=>ModConfigurations.AutoSortDefault(isolated.E,true),"explicit incompatibility rejects default sort application");Check(original.SequenceEqual(File.ReadAllBytes(isolated.E.Mods)),"failed automatic sort preserves default file bytes");}
  static object Link(string method,params object[] args){var type=typeof(Engine).Assembly.GetType("PZ3D.ModWorkshopLink");Check(type!=null,"safe ordinary workshop link helper exists");try{return type.GetMethod(method,BindingFlags.Static|BindingFlags.NonPublic|BindingFlags.Public).Invoke(null,args);}catch(TargetInvocationException x){throw x.InnerException;}}
  static Dictionary<string,object> P(object id){return new Dictionary<string,object>{{"workshopId",id}};}
  static void ErrorMembership(){var f=new Fixture();f.Mod("A");var ids=new[]{"ZombieBuddy","Missing"," A "};Original(Sort(f,ids),ids,"error preview retains every supplied row including managed components");}
  static void LargeGraph(){string[] ids=Enumerable.Range(0,2000).Select(i=>"N"+i).ToArray();var entries=ids.Select((id,i)=>new SaveProfiles.Entry{id=id,requires=new[]{i==0?"N1":"N"+(i-1)},loadAfter=new string[0],loadBefore=new string[0],conflicts=new string[0]}).ToList();var method=typeof(ModConfigurations).GetMethod("Order",BindingFlags.Static|BindingFlags.NonPublic);var result=D(method.Invoke(null,new object[]{ids,entries,new List<string>(),new HashSet<string>(StringComparer.Ordinal)}));Original(result,ids,"maximum-size dependency chain blocked by cycle preserves input without recursion");var cycle=((IEnumerable)result["cycles"]).Cast<IEnumerable>().Single().Cast<object>().Select(x=>x.ToString()).ToArray();Check(cycle.SequenceEqual(new[]{"N0","N1"})&&Strings(result,"blockedByCycles").SequenceEqual(ids.Skip(2)),"large residual graph separates two cycle members from 1998 blocked nodes");}
  static void HostPolicy(){Check(ModernController.ModWorkshopAction("modOpenWorkshop")&&!ModernController.ModWorkshopAction("openOfficial"),"ordinary workshop action remains separate from fixed author links");var j=new JavaScriptSerializer();Func<Dictionary<string,object>,string> request=payload=>j.Serialize(new{id="ordinary-mod",action="modOpenWorkshop",payload=payload});Check((string)ModernHostPolicy.Validate("https://orange.local/index.html",request(P("12345")))["action"]=="modOpenWorkshop","trusted web host accepts strict ordinary workshop action");Refuses(()=>ModernHostPolicy.Validate("https://orange.local/index.html",request(new Dictionary<string,object>{{"workshopId","12345"},{"path","C:\\arbitrary"}})),"web validator refuses arbitrary path key");Refuses(()=>ModernHostPolicy.Validate("https://orange.local/index.html",request(P(12345))),"web validator refuses numeric payload instead of canonical string");Refuses(()=>ModernHostPolicy.Validate("https://example.org/index.html",request(P("12345"))),"untrusted web origin cannot invoke ordinary workshop action");}
  static void Links(){var f=new Fixture();const string id="99999912345";string root=Path.Combine(f.E.Workshop,id,"mods/Ordinary");Put(Path.Combine(root,"42/mod.info"),"id=Ordinary\n");Check((string)Link("Resolve",f.E,P(id))=="https://steamcommunity.com/sharedfiles/filedetails/?id="+id,"current ordinary workshop item resolves only fixed official URL");Check(!WorkshopWorker.AllowItem(ulong.Parse(id)),"ordinary open does not widen fixed download allowlist");string opened=null;Link("Open",f.E,P(id),false,(Action<string>)(url=>opened=url));Check(opened!=null&&opened.EndsWith("="+id),"injected opener receives verified official page");Refuses(()=>Link("Open",f.E,P(id),true,(Action<string>)(url=>opened="forbidden")),"test mode never opens browser");Check(opened!="forbidden","rejected test request never invokes opener");foreach(object bad in new object[]{null,123,"","0","01","+123","123 ","123/456","https://steamcommunity.com/","18446744073709551616","123\n"})Refuses(()=>Link("Resolve",f.E,P(bad)),"invalid workshop identity is refused");Refuses(()=>Link("Resolve",f.E,new Dictionary<string,object>{{"workshopId",id},{"url","https://example.org"}}),"extra external URL key is refused");Refuses(()=>Link("Resolve",f.E,P("7654321")),"uninstalled arbitrary workshop item is refused");SaveProfiles.Catalog(f.E);Directory.Delete(root,true);Refuses(()=>Link("Resolve",f.E,P(id)),"fresh source validation refuses removed item despite cached catalog");f.Mod("Local","workshopId="+id+"\n");Refuses(()=>Link("Resolve",f.E,P(id)),"local author metadata cannot claim workshop provenance");}
  public static int Main(){try{Metadata();Components();LargeGraph();Preservation();ErrorMembership();HostPolicy();Links();ModConfigurationsTests.Run();SaveProfilesTests.Run();Console.WriteLine("ModSorting: "+assertions+" focused assertions passed.");return 0;}catch(Exception x){Console.WriteLine(x);return 1;}}
 }
}
